import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p56_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor conv2d_asym_5x7_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv2d_asym_5x7_cuda", &conv2d_asym_5x7_cuda, "Asymmetric 5x7 conv2d (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Tile dimensions for output spatial positions
#define TILE_W 16
#define TILE_H 8
// Channel chunk size for shared memory staging
#define C_CHUNK 8

// Each CTA handles a TILE_H x TILE_W output tile for one (batch, out_channel_block) pair.
// blockDim = (TILE_W, TILE_H) = (16, 8) = 128 threads
// Each thread computes one output element; accumulates over C_CHUNK input channels at a time.
__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,   // [N, Cin, H, W]
    const float* __restrict__ weight,  // [Cout, Cin, kH, kW]
    const float* __restrict__ bias,    // [Cout] or nullptr
    float* __restrict__ output,        // [N, Cout, Hout, Wout]
    int N, int Cin, int H, int W,
    int Cout, int kH, int kW,
    int Hout, int Wout,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w)
{
    // Grid: (ceil(Wout/TILE_W), ceil(Hout/TILE_H), N*Cout)
    const int tile_col = blockIdx.x;
    const int tile_row = blockIdx.y;
    const int nc       = blockIdx.z;  // n * Cout + oc
    const int n        = nc / Cout;
    const int oc       = nc % Cout;

    const int tx = threadIdx.x;  // [0, TILE_W)
    const int ty = threadIdx.y;  // [0, TILE_H)

    // Output pixel this thread is responsible for
    const int out_x = tile_col * TILE_W + tx;
    const int out_y = tile_row * TILE_H + ty;

    // Shared memory for input halo tile: (TILE_H*stride_h + (kH-1)*dil_h) x (TILE_W*stride_w + (kW-1)*dil_w) x C_CHUNK
    // For the benchmark case stride=1, kH=5, kW=7, dil=1: halo_h=12, halo_w=22
    // Use conservative static sizing; padded by 1 to avoid bank conflicts on last dim
    // Max halo: TILE_H + kH - 1 = 8 + 5 - 1 = 12; TILE_W + kW - 1 = 16 + 7 - 1 = 22
    // With C_CHUNK=8: 12 * 23 * 8 = 2208 floats = 8832 bytes
    extern __shared__ float smem[]; // dynamically sized

    // smem layout: [halo_h][halo_w_padded][C_CHUNK]
    // Compute actual halo sizes from runtime params
    const int halo_h = TILE_H * stride_h + (kH - 1) * dil_h;  // input rows needed
    const int halo_w = TILE_W * stride_w + (kW - 1) * dil_w;  // input cols needed
    const int halo_w_pad = halo_w + 1;  // +1 to avoid bank conflicts

    // Top-left corner of the input tile this CTA reads
    const int in_y0 = tile_row * TILE_H * stride_h - pad_h;
    const int in_x0 = tile_col * TILE_W * stride_w - pad_w;

    float acc = 0.0f;
    const bool valid_out = (out_x < Wout && out_y < Hout);

    // Iterate over input channels in C_CHUNK slices
    for (int ic_base = 0; ic_base < Cin; ic_base += C_CHUNK) {
        const int ic_end = min(ic_base + C_CHUNK, Cin);
        const int c_count = ic_end - ic_base;

        // Collaboratively load input halo into shared memory
        // Total elements: halo_h * halo_w * c_count
        const int total_load = halo_h * halo_w * c_count;
        const int tid = ty * TILE_W + tx;
        const int block_threads = TILE_W * TILE_H;

        for (int idx = tid; idx < total_load; idx += block_threads) {
            int tmp = idx;
            const int lc = tmp % c_count; tmp /= c_count;
            const int lw = tmp % halo_w;  tmp /= halo_w;
            const int lh = tmp;

            const int iy = in_y0 + lh;
            const int ix = in_x0 + lw;
            const int ic = ic_base + lc;

            float val = 0.0f;
            if (iy >= 0 && iy < H && ix >= 0 && ix < W && ic < Cin) {
                val = input[((n * Cin + ic) * H + iy) * W + ix];
            }
            smem[(lh * halo_w + lw) * (C_CHUNK + 1) + lc] = val;
        }
        __syncthreads();

        // Compute partial convolution for this channel chunk
        if (valid_out) {
            // Input pixel for out (out_y, out_x) starts at (out_y*stride_h, out_x*stride_w) in padded space
            // which is (out_y*stride_h - pad_h, out_x*stride_w - pad_w) in unpadded, i.e. offset from in_y0
            const int smem_y0 = ty * stride_h;  // offset into smem for this thread's output
            const int smem_x0 = tx * stride_w;

            for (int kh = 0; kh < kH; ++kh) {
                for (int kw = 0; kw < kW; ++kw) {
                    const int smem_y = smem_y0 + kh * dil_h;
                    const int smem_x = smem_x0 + kw * dil_w;
                    for (int lc = 0; lc < c_count; ++lc) {
                        const float in_val = smem[(smem_y * halo_w + smem_x) * (C_CHUNK + 1) + lc];
                        const int ic = ic_base + lc;
                        const float w_val = weight[((oc * Cin + ic) * kH + kh) * kW + kw];
                        acc += in_val * w_val;
                    }
                }
            }
        }
        __syncthreads();
    }

    if (valid_out) {
        if (bias != nullptr) acc += bias[oc];
        output[((n * Cout + oc) * Hout + out_y) * Wout + out_x] = acc;
    }
}

torch::Tensor conv2d_asym_5x7_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 4, "input must be 4D");
    TORCH_CHECK(weight.dim() == 4, "weight must be 4D");
    TORCH_CHECK(groups == 1, "groups must be 1");

    const int N    = input.size(0);
    const int Cin  = input.size(1);
    const int H    = input.size(2);
    const int W    = input.size(3);
    const int Cout = weight.size(0);
    const int kH   = weight.size(2);
    const int kW   = weight.size(3);

    TORCH_CHECK(weight.size(1) == Cin, "weight Cin mismatch");

    const int Hout = (H + 2 * pad_h - dil_h * (kH - 1) - 1) / stride_h + 1;
    const int Wout = (W + 2 * pad_w - dil_w * (kW - 1) - 1) / stride_w + 1;

    auto output = torch::empty({N, Cout, Hout, Wout}, input.options());

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias.value().defined()) {
        bias_ptr = bias.value().data_ptr<float>();
    }

    // Shared memory size: halo_h * halo_w * (C_CHUNK+1) floats (padded to avoid bank conflicts)
    const int halo_h = TILE_H * stride_h + (kH - 1) * dil_h;
    const int halo_w = TILE_W * stride_w + (kW - 1) * dil_w;
    const int smem_bytes = halo_h * halo_w * (C_CHUNK + 1) * sizeof(float);

    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (Wout + TILE_W - 1) / TILE_W,
        (Hout + TILE_H - 1) / TILE_H,
        N * Cout
    );

    // Make inputs contiguous in NCHW format
    auto input_c  = input.contiguous();
    auto weight_c = weight.contiguous();

    conv2d_tiled_kernel<<<grid, block, smem_bytes>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, Cin, H, W,
        Cout, kH, kW,
        Hout, Wout,
        stride_h, stride_w,
        pad_h, pad_w,
        dil_h, dil_w
    );

    C10_CUDA_CHECK(cudaGetLastError());
    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs a standard 2D convolution operation with asymmetric input and kernel sizes.

        Args:
            in_channels (int): Number of channels in the input tensor.
            out_channels (int): Number of channels produced by the convolution.
            kernel_size (tuple): Tuple of two integers representing the height and width of the convolution kernel.
            stride (tuple, optional): Tuple of two integers representing the stride in the height and width dimensions. Defaults to (1, 1).
            padding (tuple, optional): Tuple of two integers representing the padding in the height and width dimensions. Defaults to (0, 0).
            dilation (tuple, optional): Tuple of two integers representing the dilation in the height and width dimensions. Defaults to (1, 1).
            groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
            bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
        """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv2d = nn.Conv2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        # Enable cuDNN benchmark to select optimal algorithm for this shape
        torch.backends.cudnn.benchmark = True
        # Guard: use channels-last fast path when groups==1 and dilation==(1,1)
        dil = dilation if isinstance(dilation, tuple) else (dilation, dilation)
        self._use_channels_last = (groups == 1 and dil == (1, 1))
        if self._use_channels_last:
            self.conv2d = self.conv2d.to(memory_format=torch.channels_last)
            # Explicitly make weight channels-last contiguous so cuDNN avoids internal filter repacking
            self.conv2d.weight = nn.Parameter(self.conv2d.weight.contiguous(memory_format=torch.channels_last))
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Exact-shape fast path: custom shared-memory tiled CUDA kernel
                if (x.is_cuda and
                        x.dtype == torch.float32 and
                        self.conv2d.groups == 1 and
                        x.dim() == 4 and
                        x.shape[1] == self.conv2d.in_channels):
                    stride = self.conv2d.stride
                    padding = self.conv2d.padding
                    dilation = self.conv2d.dilation
                    w = self.conv2d.weight
                    b = self.conv2d.bias
                    return _stark_get_extension().conv2d_asym_5x7_cuda(
                        x.contiguous(),
                        w.contiguous(),
                        b,
                        stride[0], stride[1],
                        padding[0], padding[1],
                        dilation[0], dilation[1],
                        self.conv2d.groups
                    )
                # Fallback: channels-last cuDNN path
                if self._use_channels_last and x.is_cuda:
                    if not x.is_contiguous(memory_format=torch.channels_last):
                        x = x.contiguous(memory_format=torch.channels_last)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return self.conv2d(x)
        # <<<END_IMPROVE>>>
